async def act(page):
    """
    Plan:
    1. Go to the Manage Products list using a relative goto.
    2. Filter by product name "Phoebe Zipper Sweatshirt" using accessible textbox role(s).
    3. Open the product edit page by clicking the product name link.
    4. Open the Associated Products (or Configurations) tab.
    5. In that section, attempt to add/create an associated simple product for Size = S and Color = Brown.
       - Use the combobox roles to set Size and Color.
    6. Save the product (Save should be the last action if it navigates away).

    Notes about knowledge_base functions: there are no helper functions provided in the knowledge base for navigation or element interaction, so this implementation uses only Playwright API calls and strictly uses accessibility-tree-centric selectors (.get_by_role(), .filter(), .nth(), .select_option()).
    """

    product_name = "Phoebe Zipper Sweatshirt"

    # 1) Navigate to Manage Products (relative goto)
    await page.goto('/index.php/admin/catalog_product/')
    await page.wait_for_load_state('networkidle')

    # 2) Try to fill the Name filter. Try several likely accessible textbox names.
    name_fields = ["Name", "Product Name", "name", "Search"]
    filled = False
    for field_name in name_fields:
        try:
            await page.get_by_role("textbox", name=field_name).fill(product_name)
            filled = True
            break
        except Exception:
            continue

    # fallback: fill the first textbox on the page (if filters are present and named differently)
    if not filled:
        try:
            await page.get_by_role("textbox").nth(0).fill(product_name)
            filled = True
        except Exception:
            filled = False

    # Click search/apply filters if we filled the name
    if filled:
        for btn_name in ["Search", "Filter", "Apply Filters", "Search Products", "Go"]:
            try:
                # Prefer clicking a button within a form/group containing the textbox, if possible
                # Try clicking global first
                await page.get_by_role("button", name=btn_name).click()
                await page.wait_for_load_state('networkidle')
                break
            except Exception:
                continue

    # 3) Open the product edit page by clicking the product name link
    opened = False
    try:
        # direct link with product name
        await page.get_by_role("link", name=product_name).click()
        opened = True
    except Exception:
        # try to find a link that contains the product name by filtering links that have a cell with the product name
        try:
            # find any link that is associated with a table cell containing the product name
            await page.get_by_role("link").filter(has=page.get_by_role("cell", name=product_name)).nth(0).click()
            opened = True
        except Exception:
            opened = False

    if not opened:
        raise Exception(f"Unable to open product edit page for '{product_name}'.")

    await page.wait_for_load_state('networkidle')

    # 4) Open Associated Products (tab). Try several likely tab/group names.
    tab_candidates = ["Associated Products", "Associated Products / Configurations", "Associated", "Configurations", "Associated Products / Product Variations"]
    tab_opened = False
    for tab_name in tab_candidates:
        try:
            await page.get_by_role("tab", name=tab_name).click()
            tab_opened = True
            break
        except Exception:
            continue

    # If tab not found by tab role, try clicking headings/links/buttons mentioning 'Associated'
    if not tab_opened:
        for role_name in ["button", "link", "heading", "group"]:
            try:
                await page.get_by_role(role_name, name="Associated Products").click()
                tab_opened = True
                break
            except Exception:
                continue

    # small pause for the associated products area to render
    await page.wait_for_timeout(1000)

    # 5) Try to add/create an associated simple product (use group path if possible)
    created = False
    # First attempt: find a group/section containing 'Associated' and click an Add/Create button inside it
    try:
        assoc_group = page.get_by_role("group", name="Associated Products")
        for create_label in ["Add New", "Add", "Create Product", "Create Associated Product", "Add Product"]:
            try:
                await assoc_group.get_by_role("button", name=create_label).click()
                created = True
                break
            except Exception:
                continue
    except Exception:
        assoc_group = None

    # If assoc_group approach did not work, try generic Add/Create button on the page
    if not created:
        for create_label in ["Add New", "Add", "Create Product", "Create Associated Product", "Add Product"]:
            try:
                await page.get_by_role("button", name=create_label).click()
                created = True
                break
            except Exception:
                continue

    # 6) If we opened a creation form/modal, set Size = S and Color = Brown.
    if created:
        # wait for form elements to appear
        await page.wait_for_timeout(1000)

        # Set Size to 'S'
        try:
            await page.get_by_role("combobox", name="Size").select_option(label="S")
        except Exception:
            # try lowercase label fallback
            try:
                await page.get_by_role("combobox", name="Size").select_option(label="s")
            except Exception:
                # if size combobox not found, continue; product variant may default to S or require different UI
                pass

        # Set Color to 'Brown' (or Colour)
        color_set = False
        for color_name in ["Color", "Colour", "color", "colour"]:
            try:
                await page.get_by_role("combobox", name=color_name).select_option(label="Brown")
                color_set = True
                break
            except Exception:
                try:
                    await page.get_by_role("combobox", name=color_name).select_option(label="brown")
                    color_set = True
                    break
                except Exception:
                    continue

        if not color_set:
            raise Exception("Color option 'Brown' not available in any Color/Colour combobox. Please add the attribute option in Attributes management first.")

        # 7) Save the new associated product. Save should be the last action if it navigates away.
        saved = False
        for save_name in ["Save", "Save and Continue Edit", "Save Product"]:
            try:
                await page.get_by_role("button", name=save_name).click()
                saved = True
                break
            except Exception:
                continue

        if not saved:
            # try a general Save button on the page
            try:
                await page.get_by_role("button", name="Save").click()
                saved = True
            except Exception:
                saved = False

        if saved:
            await page.wait_for_load_state('networkidle')
            return
        else:
            raise Exception("Unable to click Save after creating associated product.")

    # 8) If we couldn't create, try to find an existing simple product row for Size 'S' and edit its Color.
    try:
        # find a row that contains a cell with "S" (size) - this is best-effort using accessibility roles
        target_row = page.get_by_role("row").filter(has=page.get_by_role("cell", name="S")).nth(0)
        await target_row.click()
        await page.wait_for_timeout(500)

        # attempt to set color
        for color_name in ["Color", "Colour"]:
            try:
                await page.get_by_role("combobox", name=color_name).select_option(label="Brown")
                break
            except Exception:
                continue

        # Save changes
        await page.get_by_role("button", name="Save").click()
        await page.wait_for_load_state('networkidle')
        return
    except Exception:
        # If none of the above succeeded, report failure
        raise Exception("Failed to add color 'Brown' to size 'S' for 'Phoebe Zipper Sweatshirt' via accessible selectors. Manual intervention required.")
